import { readdirSync, readFileSync, statSync } from 'node:fs'
import { join } from 'node:path'
import { describe, expect, it } from 'vitest'

function collectVueFiles(directory: string): string[] {
  return readdirSync(directory).flatMap((name) => {
    const path = join(directory, name)
    if (name === '__tests__' || !statSync(path).isDirectory()) return name.endsWith('.vue') ? [path] : []
    return collectVueFiles(path)
  })
}

function accessComponentSource() {
  const directory = join(import.meta.dirname, '..')
  const files = collectVueFiles(directory)
  expect(files.length, 'access components are not present yet').toBeGreaterThan(0)
  return files.map((path) => readFileSync(path, 'utf8')).join('\n')
}

describe('access component state contract', () => {
  it('represents protected records and server allowed actions explicitly', () => {
    const source = accessComponentSource()
    expect(source).toMatch(/protected/)
    expect(source).toMatch(/allowed_actions/)
    expect(source).toMatch(/read[-_ ]?only|readonly/i)
  })

  it('renders write controls only from the returned action set and exposes forbidden/conflict states', () => {
    const source = accessComponentSource()
    expect(source).toMatch(/allowed_actions.*(includes|\.includes)/s)
    expect(source).toMatch(/403|forbidden|protected[_A-Z]?user/i)
    expect(source).toMatch(/409|conflict|current_version|reload/i)
  })

  it('explains that disabling a custom role blocks new assignments but keeps existing effects', () => {
    const source = accessComponentSource()
    expect(source).toMatch(/!props\.role\.active|!role\.active|role\.active.*selectedRoleIds/s)
    expect(source).toMatch(/existing|already|remain|current/i)
    expect(source).toMatch(/assignment/i)
  })

  it('does not render password or session secrets from user and audit response data', () => {
    const source = accessComponentSource()
    expect(source).not.toMatch(/\{\{\s*(?:user|event|query\.data\.value|props\.user)\.[^}]*\b(password|password_hash|session_id|token|hash)\b[^}]*\}\}/i)
    expect(source).not.toMatch(/before\.(password|token|session_id|hash)|after\.(password|token|session_id|hash)/i)
  })
})

import { existsSync, readFileSync } from 'node:fs'
import { resolve } from 'node:path'
import { describe, expect, it } from 'vitest'

const appRoot = resolve(import.meta.dirname, '../../..')
const pagesRoot = resolve(appRoot, 'pages')

const hrRouteFiles = [
  'hr/index.vue',
  'hr/employees/new.vue',
  'hr/employees/[employeeId].vue',
  'hr/employees/[employeeId]/edit.vue',
  'hr/employees/[employeeId]/access.vue',
  'hr/departments/index.vue',
  'hr/departments/new.vue',
  'hr/departments/[departmentId].vue',
  'hr/departments/[departmentId]/edit.vue',
  'hr/documents/index.vue',
  'hr/departments/[departmentId]/documents/new.vue',
  'hr/departments/[departmentId]/documents/[documentId].vue',
  'hr/departments/[departmentId]/documents/[documentId]/edit.vue',
]

const capabilityGatedFiles = [
  'pages/hr/index.vue',
  'components/hr/DirectoryTable.vue',
  'components/hr/EmployeeGeneralForm.vue',
  'components/hr/EmployeeCard.vue',
  'components/hr/DepartmentTable.vue',
  'components/hr/DocumentList.vue',
]

describe('routed HR pages', () => {
  it('ships each employee, department, and document route from the HR pillar', () => {
    for (const route of hrRouteFiles) {
      expect(existsSync(resolve(pagesRoot, route)), route).toBe(true)
    }
  })
})

describe('HR capability boundaries', () => {
  it('uses the shared useAccess capability source for HR visibility and writes', () => {
    let sources = ''
    for (const relative of capabilityGatedFiles) {
      const source = readFileSync(resolve(appRoot, relative), 'utf8')
      expect(source, relative).toMatch(/useAccess/)
      expect(source, relative).not.toMatch(/\.value\?\.role|role\s*===/)
      sources += source
    }
    expect(sources).toMatch(/hr\.employees\.access_status\.read/)
    expect(sources).toMatch(/hr\.employees\.manage/)
    expect(sources).toMatch(/hr\.employees\.archive/)
    expect(sources).toMatch(/hr\.departments\.manage/)
    expect(sources).toMatch(/hr\.documents\.manage/)
  })

  it('does not retain a legacy HR access editor or write endpoint client', () => {
    const source = readFileSync(resolve(appRoot, 'composables/useHrEmployees.ts'), 'utf8')
    expect(source).not.toMatch(/useGrantHrAccess|useUpdateHrAccess|useRevokeHrAccess/)
    expect(source).not.toMatch(/\/access/)
  })

  it('redirects the legacy HR access page into system account administration', () => {
    const path = resolve(pagesRoot, 'hr/employees/[employeeId]/access.vue')
    expect(existsSync(path), 'missing legacy HR access redirect route').toBe(true)
    if (!existsSync(path)) return
    const source = readFileSync(path, 'utf8')
    expect(source).toMatch(/navigateTo/)
    expect(source).toMatch(/settings\/users/)
    expect(source).not.toMatch(/useGrantHrAccess|useUpdateHrAccess|useRevokeHrAccess|method:\s*['"](POST|PATCH|DELETE)/)
  })
})

import { readFileSync } from 'node:fs'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'
import { compileTemplate, parse } from '@vue/compiler-sfc'
import { renderToString } from '@vue/server-renderer'
import ts from 'typescript'
import * as Vue from 'vue'
import { createSSRApp, defineComponent, h, type Component, type RenderFunction, type VNode } from 'vue'
import { describe, expect, it } from 'vitest'

const webRoot = resolve(dirname(fileURLToPath(import.meta.url)), '../../../../')

const NuxtLinkStub = defineComponent({
  props: { to: { type: [String, Object], default: '#' } },
  setup(props, { slots }) {
    return () => h('a', { href: typeof props.to === 'string' ? props.to : '#' }, slots.default?.())
  },
})

function loadShared(name: string): Component {
  const filename = resolve(webRoot, `app/components/shared/${name}.vue`)
  const source = readFileSync(filename, 'utf8')
  const parsed = parse(source, { filename })
  if (parsed.errors.length) throw parsed.errors[0]
  if (!parsed.descriptor.template) throw new Error(`${name}.vue has no template`)

  const compiled = compileTemplate({
    source: parsed.descriptor.template.content,
    filename,
    id: `shared-${name}`,
    compilerOptions: { mode: 'function', expressionPlugins: ['typescript'] },
  })
  if (compiled.errors.length) throw compiled.errors[0]

  const runnableCode = ts.transpileModule(compiled.code, {
    compilerOptions: { target: ts.ScriptTarget.ES2020, module: ts.ModuleKind.None },
  }).outputText
  const render = new Function('Vue', runnableCode)(Vue) as RenderFunction
  return defineComponent({
    name,
    props: {
      title: String,
      description: String,
      backTo: [String, Object],
      backLabel: String,
    },
    setup(props) {
      return { props }
    },
    render,
  })
}

async function renderShared(
  name: string,
  props: Record<string, unknown> = {},
  slots: Record<string, () => VNode | VNode[]> = {},
): Promise<string> {
  const app = createSSRApp({ render: () => h(loadShared(name), props, slots) })
  app.component('NuxtLink', NuxtLinkStub)
  return renderToString(app)
}

describe('shared composition rendered contracts', () => {
  it('renders PageHeader back link, title, description, and actions in order', async () => {
    const html = await renderShared(
      'PageHeader',
      { title: 'Tasks', description: 'Track delivery', backTo: '/tasks', backLabel: 'Back' },
      {
        title: () => h('span', { 'data-slot-content': 'title' }, 'Title slot'),
        actions: () => h('button', { type: 'button' }, 'Create'),
      },
    )

    expect(html).toContain('href="/tasks"')
    expect(html).toContain('Back')
    expect(html).toContain('Title slot')
    expect(html).toContain('Track delivery')
    expect(html).toContain('Create')
    expect(html.indexOf('Back')).toBeLessThan(html.indexOf('Title slot'))
    expect(html.indexOf('Title slot')).toBeLessThan(html.indexOf('Create'))
  })

  it('renders search and controls in the first row, with active filters below and view last in the first row', async () => {
    const html = await renderShared('FilterBar', {}, {
      search: () => h('input', { 'aria-label': 'Search' }),
      default: () => h('button', { type: 'button' }, 'All states'),
      active: () => h('span', { 'data-filter': 'active' }, 'State: Done'),
      view: () => h('button', { type: 'button' }, 'Board'),
    })

    expect(html).toContain('aria-label="Search"')
    expect(html).toContain('All states')
    expect(html).toContain('State: Done')
    expect(html).toContain('Board')
    const searchMarker = html.indexOf('data-slot="search"')
    const controlsMarker = html.indexOf('data-slot="controls"')
    const viewMarker = html.indexOf('data-slot="view"')
    const activeRowMarker = html.indexOf('data-slot="active-row"')
    expect(searchMarker).toBeGreaterThanOrEqual(0)
    expect(controlsMarker).toBeGreaterThan(searchMarker)
    expect(viewMarker).toBeGreaterThan(controlsMarker)
    expect(activeRowMarker).toBeGreaterThan(viewMarker)
  })

  it('renders EmptyState as status with title, description, icon, and action', async () => {
    const html = await renderShared(
      'EmptyState',
      { title: 'No tasks', description: 'Create one to get started' },
      {
        icon: () => h('svg', { 'aria-hidden': 'true' }),
        action: () => h('button', { type: 'button' }, 'Create task'),
      },
    )

    expect(html).toMatch(/role="status"/)
    expect(html).toContain('No tasks')
    expect(html).toContain('Create one to get started')
    expect(html).toContain('aria-hidden="true"')
    expect(html).toContain('Create task')
  })
})
